#include "resident/kernel/catalog_section_observation.hpp"
// 独立目录严格选择书面承诺来源；旧模板15没有这个目录时完全保原行为。
#include "visit_appointment_attendance.hpp"
#include "visit_appointment_boundary.hpp"
#include <set>
namespace hanmo::resident {namespace {
void unique(const BoundaryValue& v,const StableId& at){std::set<StableId> keys;for(const auto& p:boundary::object(v,at))if(!keys.insert(p.first).second)boundary::fail("DuplicateVisitAppointmentAttendanceField",at);}
}
Outcome<VisitAppointmentAttendanceCatalog> decode_visit_appointment_attendance_catalog(const BoundaryValue& value){try{using namespace boundary;unique(value,visit_appointment_attendance_module);fields(value,{"version","invitation_policy_ids"},{},visit_appointment_attendance_module);VisitAppointmentAttendanceCatalog out;out.version=get_int(value,"version",visit_appointment_attendance_module);if(out.version!=1)unsupported("UnsupportedVisitAppointmentAttendanceVersion",visit_appointment_attendance_module);out.invitation_policy_ids=strings(field(value,"invitation_policy_ids",visit_appointment_attendance_module),"invitation_policy_ids");if(out.invitation_policy_ids.empty()||out.invitation_policy_ids.size()>4096)fail("InvalidVisitAppointmentAttendancePolicies","invitation_policy_ids");std::set<StableId> seen;for(const auto& id:out.invitation_policy_ids)if(id.empty()||id.size()>256||!seen.insert(id).second)fail("InvalidVisitAppointmentAttendancePolicy",id);return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_visit_appointment_attendance_catalog(const VisitAppointmentAttendanceCatalog& c){BoundaryValue::Array ids;for(const auto& id:c.invitation_policy_ids)ids.emplace_back(id);return boundary::obj({{"version",BoundaryValue{c.version}},{"invitation_policy_ids",BoundaryValue{std::move(ids)}}});}
Status validate_visit_appointment_attendance_catalog(const VisitAppointmentAttendanceCatalog& c,const VisitAppointmentCatalog& invitations,const PersonalAppointmentAttendanceCatalog& original,const PersonalAppointmentCatalog& appointments){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 59, "VisitAppointmentAttendanceCatalog", "validate_visit_appointment_attendance_catalog", &c);
if(c.version!=1||c.invitation_policy_ids.empty()||c.invitation_policy_ids.size()>4096)return common_failure("InvalidVisitAppointmentAttendancePolicies");std::set<StableId> seen;for(const auto&id:c.invitation_policy_ids)if(id.empty()||id.size()>256||!seen.insert(id).second)return common_failure("InvalidVisitAppointmentAttendancePolicy",id);if((invitations.version!=1&&invitations.version!=2)||invitations.version!=appointments.version)return common_failure("VisitAppointmentAttendanceProfileRequired");auto valid=validate_personal_appointment_attendance_catalog(original,appointments);if(!valid.ok)return valid;for(const auto& id:c.invitation_policy_ids){const auto* policy=visit_appointment_policy(invitations,id);if(!policy||!policy->inviter_commits_fixed_window||std::none_of(original.policies.begin(),original.policies.end(),[&](const auto& p){return p.appointment_policy_id==policy->appointment_policy_id;}))return common_failure("VisitAppointmentAttendanceOriginalPolicyRequired",id);}return common_success();}
Outcome<bool> decode_visit_appointment_attendance_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){const auto* source=scenario.find(visit_appointment_attendance_module);if(!source)return {true,false,{}};auto parsed=decode_visit_appointment_attendance_catalog(*source);if(!parsed.ok)return {false,{},parsed.error};auto invitations=decode_visit_appointment_profile(scenario,capabilities);if(!invitations.ok)return invitations;auto original=decode_personal_appointment_attendance_profile(scenario,capabilities);if(!original.ok)return original;if(!invitations.value||!original.value)return {false,{},common_failure("VisitAppointmentAttendanceProfileRequired").error};if(std::find(capabilities.begin(),capabilities.end(),"visit_appointment_attendance_v1")==capabilities.end())return {false,{},common_failure("VisitAppointmentAttendanceCapabilityRequired").error};return {true,true,{}};}
}
